#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 5;

    // Allouer un tableau de n entiers
    int *tab = malloc(n * sizeof(int));
    if (tab == NULL) {
        printf("Erreur d'allocation\n");
        return 1;
    }

    for (int i = 0; i < n; i++) {
        tab[i] = i * 10;
    }

    for (int i = 0; i < n; i++) {
        printf("%d ", tab[i]);
    }
    printf("\n");

    free(tab); // libérer la mémoire
    tab = NULL; // bonne pratique
    return 0;
}
